from sim import Sim
import numpy as np

def trial(torso,lsp,rsp,lsr,rsr,le,re,steps=400,hold=600):
    sim=Sim(); home=sim.home_ctrl();
    ctrl=home.copy();
    ctrl[10]+=torso; ctrl[11]+=lsp; ctrl[15]+=rsp; ctrl[12]+=lsr; ctrl[16]+=rsr; ctrl[14]+=le; ctrl[18]+=re
    maxx=-1
    for i in range(steps):
        sim.data.ctrl[:]=ctrl; sim.step(1); maxx=max(maxx,sim.pelvis_position()[0])
    for i in range(hold):
        sim.data.ctrl[:]=home; sim.step(1); maxx=max(maxx,sim.pelvis_position()[0])
    p=sim.pelvis_position(); b=sim.box_position();
    stable=(p[2],sim.torso_up(),b[2],np.linalg.norm(b-p))
    return maxx,p,b,stable

vals=[-0.8,-0.4,0,0.4,0.8]
best=None
for torso in [-0.6,-0.3,0,0.3,0.6]:
  for sp in vals:
    for sr in [-0.6,0,0.6]:
      for e in [-1.0,-0.5,0]:
        mx,p,b,s=trial(torso,sp,sp,sr,-sr,e,e)
        if best is None or mx>best[0]:
            best=(mx,torso,sp,sr,e,p,b,s)
print('best maxx',best[0],'params',best[1:5])
print('pelvis',best[5],'box',best[6],'stable tuple pz,up,bz,bp',best[7])
PY"

